const query = $input.first().json.query || {};
const city = String(query.city || 'all').trim();
const limit = Math.min(Math.max(Number(query.limit) || 10, 1), 30);

return [{json: {
  city: city,
  limit: limit,
  skills: ['python', 'fastapi', 'backend', 'data scientist', 'data analyst', 'machine learning', 'ai engineer', 'ki entwickler', 'automation']
}}];

const settings = $('Search Settings').first().json;
const response = $input.first().json;
const jobs = Array.isArray(response.data) ? response.data : [];
const city = settings.city.toLowerCase();
const seen = new Set();
const matches = [];

function text(value) {
  return String(value || '').toLowerCase();
}

for (const job of jobs) {
  const title = text(job.title);
  const location = text(job.location);
  const tags = Array.isArray(job.tags) ? job.tags.join(' ').toLowerCase() : '';
  const description = text(job.description).replace(/<[^>]*>/g, ' ');
  const url = String(job.url || '');
  if (!url || seen.has(url)) continue;
  seen.add(url);

  const title_match = settings.skills.some(skill => title.includes(skill));
  if (!title_match) continue;

  const remote = Boolean(job.remote) || location.includes('remote');
  if (city !== 'all' && city !== 'remote') {
    if (!location.includes(city) && !remote) continue;
  }
  if (city === 'remote' && !remote) continue;

  let score = 0;
  if (/python|fastapi/.test(title)) score += 7;
  if (/backend|data scientist|data analyst|machine learning/.test(title)) score += 5;
  if (/ai engineer|ki entwickler|automation/.test(title)) score += 4;
  if (/junior|trainee|praktik|intern|entry.level|berufseinsteiger/.test(title)) score += 4;
  if (/fastapi|python|sql|postgresql/.test(description + ' ' + tags)) score += 2;
  if (/senior|lead|principal|staff|head of/.test(title)) score -= 8;
  if (score <= 0) continue;

  matches.push({
    title: job.title || '',
    company: job.company_name || '',
    location: job.location || '',
    remote: remote,
    score: score,
    link: url,
    published_at: job.created_at ? new Date(job.created_at * 1000).toISOString().slice(0, 10) : null
  });
}

matches.sort((a, b) => b.score - a.score);
return [{json: {
  project: 'job_radar',
  city: settings.city,
  checked: jobs.length,
  matching: matches.length,
  returned: Math.min(matches.length, settings.limit),
  jobs: matches.slice(0, settings.limit),
  data_source: 'Arbeitnow',
  note: 'Only the latest API page is checked. Scores are rule-based.'
}}];
